UPDATE t_payment
SET status      = 2,
    notify_time = NOW(),
    fail_reason = #{reason}
WHERE pay_no = #{payNo}
  AND status IN (0, 1)

UPDATE t_payment
SET status      = 3,
    notify_time = NOW(),
    fail_reason = #{reason}
WHERE pay_no = #{payNo}
  AND status = 0

UPDATE t_payment
SET status      = 3,
    notify_time = NOW(),
    fail_reason = #{reason}
WHERE order_no = #{orderNo}
  AND status = 0

